package com.voicetxt.reader;

import android.app.*;import android.content.*;import android.os.*;import android.graphics.Bitmap;import java.io.*;import java.util.*;

/** Expanded model languages, translation capability filtering and multi-speaker UI regression. */
public class ExpandedVoiceTest extends VoiceWarmupTest {
    final List<Activity> opened=new ArrayList<>();
    void screenshot(Activity a,String name)throws Exception{waitForIdleSync();Thread.sleep(300);Bitmap bitmap=getUiAutomation().takeScreenshot();check(bitmap!=null,"Screenshot unavailable");try(FileOutputStream out=new FileOutputStream(new File(a.getExternalFilesDir(null),name))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}
    public void onStart(){Bundle result=new Bundle();boolean success=false;VoicePackages store=VoicePackages.get(getTargetContext());SharedPreferences prefs=getTargetContext().getSharedPreferences("reading_settings",0);Map<String,?> saved=new HashMap<>(prefs.getAll());OfflineTranslation detector=null;PackageSpeakerPicker[] dialog={null};String id="expanded_voice_qa";String importedId="";String oldPhase=store.phase,oldError=store.error,oldInstalled=store.lastInstalled;
        try{
            check(VoiceModel.languages("Italian, Esperanto, Swedish, zh_Hant, English").equals(new LinkedHashSet<>(Arrays.asList("it","eo","sv","zh","en"))),"Expanded metadata names");check(VoiceModel.languages("ita sv_SE eo fil-PH cmn").equals(new LinkedHashSet<>(Arrays.asList("it","sv","eo","tl","zh"))),"Expanded metadata locales/aliases: "+VoiceModel.languages("ita sv_SE eo fil-PH cmn"));check(VoiceModel.languages("unknown und multilingual").isEmpty(),"Unknown model language accepted");check(VoiceLanguages.sample("eo").contains("1"),"Extra-language preview missing");check(TranslationText.SUPPORTED.contains("it")&&!TranslationText.SUPPORTED.contains("sv"),"Translation capabilities not separate");
            detector=new OfflineTranslation(getTargetContext());OriginalVoicePlanner planner=new OriginalVoicePlanner(detector.identifier);String[] snippets={"今天天气很好，我们一起去公园散步，欣赏美丽的风景。","The weather is beautiful today. We are reading a wonderful book together.","Oggi il tempo è molto bello. Leggiamo insieme un libro interessante.","Det är vackert väder idag. Vi läser en intressant bok tillsammans."};String[] languages={"zh","en","it","sv"};for(int i=0;i<snippets.length;i++)check(planner.detect(snippets[i],"zh").equals(languages[i]),"Original detection "+languages[i]);OriginalVoicePlanner.Batch batch=planner.plan(Arrays.asList(snippets),0,"zh",()->true);check(batch.end==1&&batch.language.equals("zh"),"Mixed-language batch boundary");try{planner.plan(Arrays.asList(snippets),0,"zh",()->false);throw new AssertionError("Cancellation ignored");}catch(java.util.concurrent.CancellationException expected){}
            OfflineVoicesActivity manager=(OfflineVoicesActivity)startActivitySync(new Intent(getTargetContext(),OfflineVoicesActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));opened.add(manager);await(()->manager.system!=null&&manager.system.initialized,"System voices not ready",30000);
            boolean hasMulti=false;for(VoiceModel pack:store.list("zh"))if(pack.speakers>10)hasMulti=true;if(!hasMulti){check(!store.busy,"User import is active");File archive=new File(getTargetContext().getExternalFilesDir(null),"qa-multi-voice.zip");check(archive.isFile(),"Test multi-speaker archive missing");store.importUri("",android.net.Uri.fromFile(archive));await(()->!store.busy,"QA import timed out",120000);check(store.phase.equals("done"),"QA import failed: "+store.error);importedId=store.lastInstalled;}
            ui(()->{VoiceModel fixture=new VoiceModel();fixture.id=id;fixture.name="Language capability fixture";fixture.speakers=1;fixture.languages.addAll(Arrays.asList("it","sv"));synchronized(store){check(!store.models.containsKey(id),"Fixture collision");store.models.put(id,fixture);}try{List<String> available=VoiceLanguages.available(manager.system,store);check(available.contains("it")&&available.contains("sv"),"Original-only language hidden");List<String> targets=VoiceLanguages.targets(manager.system,store);check(targets.contains("it")&&!targets.contains("sv"),"Translation targets include unsupported language");manager.render();check(manager.headers.containsKey("sv")&&!manager.headers.containsKey("zh-Hant"),"Management category incorrect");}finally{synchronized(store){store.models.remove(id);}}manager.expanded="zh";manager.render();});
            screenshot(manager,"qa-voice-packages.png");
            VoiceModel multi=null;for(VoiceModel pack:store.list("zh"))if(pack.speakers>10){multi=pack;break;}check(multi!=null,"Multi-speaker model missing");final VoiceModel model=multi;final int ordinal=Math.min(73,model.speakers-1);ui(()->{OfflineVoicesActivity.Item item=new OfflineVoicesActivity.Item(model,"zh",manager.speaker(model,"zh"),"QA");manager.chooseSpeaker(item);dialog[0]=manager.speakerPicker;check(dialog[0]!=null&&dialog[0].isShowing()&&dialog[0].grid.getAdapter()!=null,"Speaker grid not shown");dialog[0].host.select(ordinal);check(manager.previewKey.isEmpty(),"Selection auto-previewed");check(manager.selectedKey("zh").equals(model.key(ordinal)),"Selected speaker lost");dialog[0].search.setText(String.valueOf(ordinal+1));check(dialog[0].filtered.contains(ordinal),"Search did not find speaker");dialog[0].search.setText("999999");check(dialog[0].filtered.isEmpty(),"Empty search not handled");dialog[0].search.setText("");});
            screenshot(manager,"qa-multi-speakers.png");ui(()->{check(dialog[0].grid.getNumColumns()==2,"Speaker columns after layout");dialog[0].host.preview(ordinal);});await(()->manager.previewStarted,"Speaker preview failed",35000);ui(()->{check(manager.previewKey.equals(model.key(ordinal)),"Wrong preview speaker");dialog[0].host.preview(ordinal);check(manager.previewKey.isEmpty(),"Preview pause failed");dialog[0].dismiss();dialog[0]=null;manager.finish();});
            prefs.edit().putString("readingLanguage","").putString("chineseVoiceKey",saved.get("chineseVoiceKey") instanceof String?(String)saved.get("chineseVoiceKey"):"").apply();
            MainActivity reader=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).putExtra("book_id","expanded_voice_qa").putExtra("book_name","原文语言验证").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));opened.add(reader);await(()->reader.system!=null&&reader.system.initialized,"Reader system not ready",30000);
            final String mixed="这是中文测试，欢迎使用我爱听书。\nThe weather is beautiful today. We are reading a book together.";final int englishAt=mixed.indexOf("The weather");ui(()->{reader.stop();reader.readingLanguage="";reader.text=mixed;reader.chapters=MainActivity.parse(mixed);reader.position=0;reader.loopPlayback=false;reader.rate=2;reader.showPosition(true);reader.startReading();});await(()->reader.playing&&reader.voiceLanguage().equals("en")&&reader.latestHighlightStart>=englishAt,"Original reading did not switch to English",45000);ui(()->reader.stop());
            // Swedish has no installed voice: stop at the Swedish passage without skipping it.
            if(!VoiceLanguages.available(reader.system,store).contains("sv")){String missing="Det är vackert väder idag. Vi läser en intressant bok tillsammans.";ui(()->{reader.originalVoiceLanguage="";reader.text=missing;reader.chapters=MainActivity.parse(missing);reader.position=0;reader.showPosition(true);reader.startReading();});await(()->!reader.playing&&reader.latestStatus.contains(VoiceLanguages.name("sv",AppLanguage.locale(reader))),"Missing language not reported",15000);ui(()->check(reader.position==0,"Missing language was skipped"));}
            ui(()->{reader.chooseReadingLanguage();check(!reader.languagePicker.choices.containsKey("sv"),"Unsupported translated language shown");reader.languagePicker.dismiss();reader.stop();});
            result.putString("result","PASS: ISO languages and metadata aliases beyond original list; translation targets separate from original voices; original mixed Chinese/English automatic switching; missing Swedish voice pauses without skipping; two-column multi-speaker grid, search, exact ordinal selection without auto-preview, explicit preview/pause; one Chinese category");success=true;
        }catch(Throwable failure){result.putString("error",android.util.Log.getStackTraceString(failure));}
        finally{ui(()->{if(dialog[0]!=null)dialog[0].dismiss();for(Activity activity:opened){if(activity instanceof MainActivity)((MainActivity)activity).stop();if(!activity.isFinishing())activity.finish();}synchronized(store){store.models.remove(id);}});waitForIdleSync();if(!importedId.isEmpty()){final String cleanupId=importedId;try{await(()->!store.leases.containsKey(cleanupId),"QA package lease not released",20000);store.delete(cleanupId);await(()->!store.busy,"QA package cleanup timed out",15000);check(!store.models.containsKey(cleanupId),"QA package not removed");}catch(Exception cleanup){result.putString("cleanupError",cleanup.toString());success=false;}}store.phase=oldPhase;store.error=oldError;store.lastInstalled=oldInstalled;restore(prefs,saved);if(detector!=null)detector.close();getTargetContext().getSharedPreferences("reader_expanded_voice_qa",0).edit().clear().commit();new File(getTargetContext().getFilesDir(),"book_expanded_voice_qa.txt.position").delete();}
        finish(success?-1:0,result);
    }
}
